interface ExportCapability {
    String export();
    default String mediaType() { return "text/plain"; }
}
class CsvExport implements ExportCapability {
    public String export() { return "csv"; }
}
public class ModernInterfaceDemo {
    public static void main(String[] args) { ExportCapability e = new CsvExport(); System.out.println(e.export() + " " + e.mediaType()); }
}
